import z3

# 11 vertices
n = 11

# Create boolean variables for each possible edge
edges = {}
for i in range(n):
    for j in range(i + 1, n):
        edges[(i, j)] = z3.Bool(f"e_{i}_{j}")

solver = z3.Solver()

# Add constraints for known edges
known_edges = [(2,8), (2,6), (2,10), (3,8), (0,10)]
for i, j in known_edges:
    if i > j:
        i, j = j, i
    solver.add(edges[(i, j)] == True)

# Add degree constraints
for i in range(n):
    degree_i = []
    for j in range(n):
        if i == j:
            continue
        u, v = (i, j) if i < j else (j, i)
        degree_i.append(z3.If(edges[(u, v)], 1, 0))

    deg_sum = z3.Sum(degree_i)
    solver.add(deg_sum >= 1)
    solver.add(deg_sum <= 5)

if solver.check() == z3.sat:
    m = solver.model()
    result = []
    for i in range(n):
        for j in range(i + 1, n):
            if z3.is_true(m[edges[(i, j)]]):
                result.append((i, j))
    print("SAT")
    print(result)
else:
    print("UNSAT")
